arguments.file_text:
namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

using System.ComponentModel.DataAnnotations;

namespace RecipeHub.Models;

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Description is required.")]
    [StringLength(500, ErrorMessage = "Description must be 500 characters or fewer.")]
    public string Description { get; set; } = string.Empty;

    [Required(ErrorMessage = "Ingredients are required.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Steps are required.")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes = GetSeedRecipes();
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public IReadOnlyList<string> Categories =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null || stars is < 1 or > 5) return;
        recipe.TotalRatings++;
        recipe.RatingSum += stars;
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Description = submission.Description,
            Ingredients = submission.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = submission.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList()
        });
    }

    private static List<Recipe> GetSeedRecipes() =>
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple yet delicious pizza with fresh mozzarella, tomatoes, and basil.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps = ["Preheat oven to 475°F.", "Roll out dough on a floured surface.", "Spread crushed tomatoes evenly.", "Add sliced mozzarella.", "Bake for 10-12 minutes.", "Top with fresh basil and a drizzle of olive oil."],
            TotalRatings = 12, RatingSum = 52
        },
        new()
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "Creamy Roman pasta made with eggs, cheese, pancetta, and black pepper.",
            Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper", "Salt"],
            Steps = ["Cook spaghetti in salted boiling water.", "Fry pancetta until crisp.", "Whisk eggs with grated cheese and pepper.", "Toss hot pasta with pancetta.", "Remove from heat and stir in egg mixture.", "Serve immediately with extra cheese."],
            TotalRatings = 8, RatingSum = 35
        },
        new()
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken in a rich, spiced tomato-cream sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
            Steps = ["Marinate chicken in yogurt and spices for 1 hour.", "Grill or broil chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato sauce and spices; simmer.", "Stir in cream and cooked chicken.", "Simmer 10 minutes and serve with rice."],
            TotalRatings = 15, RatingSum = 68
        },
        new()
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
            Description = "Stir-fried rice noodles with vegetables, peanuts, and tangy sauce.",
            Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Peanuts", "Lime", "Tamarind paste", "Fish sauce", "Sugar", "Garlic"],
            Steps = ["Soak noodles in warm water for 20 minutes.", "Mix tamarind, fish sauce, and sugar for the sauce.", "Stir-fry tofu and garlic.", "Add noodles and sauce.", "Toss with bean sprouts.", "Serve with crushed peanuts and lime wedges."],
            TotalRatings = 6, RatingSum = 25
        },
        new()
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef in corn tortillas with fresh toppings.",
            Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
            Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water; simmer.", "Warm tortillas in a dry pan.", "Fill tortillas with beef.", "Add lettuce, tomato, cheese, sour cream, and salsa.", "Serve immediately."],
            TotalRatings = 10, RatingSum = 42
        },
        new()
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Description = "Fresh avocado dip with lime, cilantro, and jalapeño.",
            Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
            Steps = ["Halve and pit avocados; scoop into a bowl.", "Mash to desired consistency.", "Stir in diced onion, jalapeño, and tomato.", "Add lime juice, cilantro, and salt.", "Mix well and serve with tortilla chips."],
            TotalRatings = 9, RatingSum = 40
        },
        new()
        {
            Id = 7, Title = "Miso Soup", Category = "Japanese",
            Description = "A light, savory broth with tofu, seaweed, and scallions.",
            Ingredients = ["Dashi stock", "Miso paste", "Silken tofu", "Wakame seaweed", "Scallions"],
            Steps = ["Bring dashi stock to a simmer.", "Dissolve miso paste in a ladleful of broth.", "Add tofu cubes and wakame.", "Stir in the miso mixture.", "Garnish with sliced scallions and serve."],
            TotalRatings = 5, RatingSum = 21
        },
        new()
        {
            Id = 8, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Rich individual cakes with a molten chocolate center.",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
            Steps = ["Preheat oven to 425°F and grease ramekins.", "Melt chocolate and butter together.", "Whisk in eggs, sugar, and vanilla.", "Fold in flour gently.", "Pour into ramekins and bake 12-14 minutes.", "Invert onto plates and serve immediately."],
            TotalRatings = 18, RatingSum = 85
        }
    ];
}

