@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="star @(star <= (hoverStar ?? selectedStar) ? "filled" : "")"
                @onclick="() => SubmitRating(star)"
                @onmouseover="() => hoverStar = star"
                @onmouseout="() => hoverStar = null"
                disabled="@submitted">
            ★
        </button>
    }
    <span class="rating-info">
        @if (submitted)
        {
            <span class="thanks">Thanks for rating!</span>
        }
        @CurrentAverage.ToString("0.0") avg · @TotalRatings ratings
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentAverage { get; set; }
    [Parameter] public int TotalRatings { get; set; }

    private int? hoverStar;
    private int selectedStar;
    private bool submitted;

    private void SubmitRating(int stars)
    {
        if (submitted) return;
        selectedStar = stars;
        RecipeService.AddRating(RecipeId, stars);

        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentAverage = recipe.AverageRating;
            TotalRatings = recipe.TotalRatings;
        }
        submitted = true;
    }
}

.star-rating {
    display: flex;
    align-items: center;
    gap: 0.2rem;
}

.star {
    background: none;
    border: none;
    font-size: 1.8rem;
    cursor: pointer;
    color: #ccc;
    padding: 0;
    transition: color 0.15s;
}

.star.filled {
    color: #f5a623;
}

.star:disabled {
    cursor: default;
}

.rating-info {
    margin-left: 0.75rem;
    font-size: 0.9rem;
    color: #666;
}

.thanks {
    color: #2d6a4f;
    font-weight: 600;
    margin-right: 0.5rem;
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>

@if (successMessage is not null)
{
    <div class="alert-success">@successMessage</div>
}

<EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
    <DataAnnotationsValidator />
    <ValidationSummary />

    <div class="form-group">
        <label for="title">Title</label>
        <InputText id="title" @bind-Value="submission.Title" class="form-input" />
    </div>

    <div class="form-group">
        <label for="category">Category</label>
        <InputSelect id="category" @bind-Value="submission.Category" class="form-input">
            <option value="">— Select a category —</option>
            @foreach (var cat in RecipeService.Categories)
            {
                <option value="@cat">@cat</option>
            }
            <option value="Other">Other</option>
        </InputSelect>
    </div>

    <div class="form-group">
        <label for="description">Description</label>
        <InputTextArea id="description" @bind-Value="submission.Description" class="form-input" rows="2" />
    </div>

    <div class="form-group">
        <label for="ingredients">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" @bind-Value="submission.Ingredients" class="form-input" rows="5" />
    </div>

    <div class="form-group">
        <label for="steps">Steps (one per line)</label>
        <InputTextArea id="steps" @bind-Value="submission.Steps" class="form-input" rows="5" />
    </div>

    <button type="submit" class="btn-submit">Submit Recipe</button>
</EditForm>

@code {
    private RecipeSubmission submission = new();
    private string? successMessage;

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(submission);
        successMessage = $"\"{submission.Title}\" was submitted successfully!";
        submission = new();
    }
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.3rem;
}

.form-input {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-input:focus {
    outline: none;
    border-color: #2d6a4f;
    box-shadow: 0 0 0 2px rgba(45, 106, 79, 0.2);
}

.btn-submit {
    background: #2d6a4f;
    color: #fff;
    border: none;
    padding: 0.65rem 1.5rem;
    font-size: 1rem;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 600;
}

.btn-submit:hover {
    background: #1b4332;
}

.alert-success {
    background: #d1fae5;
    color: #065f46;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    margin-bottom: 1.5rem;
    font-weight: 500;
}

::deep .validation-message {
    color: #dc2626;
    font-size: 0.85rem;
}

::deep .validation-errors {
    color: #dc2626;
    margin-bottom: 1rem;
}

