toolArgs.file_text:
@page "/recipe/{Id:int}"
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeHub</PageTitle>

@if (recipe is null)
{
    <h1>Recipe not found</h1>
    <p><a href="/">← Back to home</a></p>
}
else
{
    <h1>@recipe.Title</h1>
    <p class="recipe-meta">Category: <a href="/category/@recipe.Category">@recipe.Category</a></p>
    <p>@recipe.Description</p>

    <h2>Ingredients</h2>
    <ul>
        @foreach (var item in recipe.Ingredients)
        {
            <li>@item</li>
        }
    </ul>

    <h2>Steps</h2>
    <ol>
        @foreach (var step in recipe.Steps)
        {
            <li>@step</li>
        }
    </ol>

    <h2>Rate this Recipe</h2>
    <StarRating RecipeId="recipe.Id" CurrentAverage="recipe.AverageRating" TotalRatings="recipe.TotalRatings" />

    <p style="margin-top:2rem;"><a href="/category/@recipe.Category">← Back to @recipe.Category recipes</a></p>
}

@code {
    [Parameter] public int Id { get; set; }

    private RecipeHub.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

